-- Campos editoriais e fontes de uma página própria por produção.
alter table public.watch_titles add column if not exists seo_title text;
alter table public.watch_titles add column if not exists seo_description text;
alter table public.watch_titles add column if not exists editorial_body text;
update public.watch_titles set seo_title='Spider-Man: Brand New Day: história e onde assistir',seo_description='Veja o que se sabe sobre Spider-Man: Brand New Day, o filme do Homem-Aranha de 2026, com ficha, contexto e situação da exibição no Brasil.',editorial_body='Spider-Man: Brand New Day integra a trajetória cinematográfica do Homem-Aranha e é uma das produções de super-heróis associadas a 2026. Quem acompanha o personagem pode consultar a ficha de referência indicada nesta página para acompanhar as informações confirmadas da produção.

Para saber onde assistir no Brasil, é importante conferir as condições de distribuição locais. Exibição em cinema, aluguel digital e disponibilidade por assinatura são modalidades diferentes e não devem ser tratadas como equivalentes. O Guia de Hoje só indicará um serviço específico quando houver confirmação confiável.' where title='Spider-Man: Brand New Day' and is_published=true;
update public.watch_titles set seo_title='The Super Mario Galaxy Movie: sinopse e onde assistir',seo_description='Conheça The Super Mario Galaxy Movie, animação ligada ao universo dos jogos Mario, e acompanhe a situação da estreia e do streaming no Brasil.',editorial_body='The Super Mario Galaxy Movie é uma animação ligada ao universo de Mario, personagem conhecido pelos jogos da Nintendo. A produção interessa tanto a quem acompanha as adaptações cinematográficas quanto a quem procura filmes de aventura e fantasia inspirados em videogames.

Nesta ficha, o Guia de Hoje reúne uma apresentação da obra e a referência de origem para consulta. A disponibilidade brasileira deve ser conferida separadamente: informações sobre lançamento não comprovam presença em streaming. Quando houver fonte verificável sobre canais, serviços ou datas, a indicação poderá ser acrescentada.' where title='The Super Mario Galaxy Movie' and is_published=true;
update public.watch_titles set seo_title='Project Hail Mary: ficção científica e onde assistir',seo_description='Descubra Project Hail Mary, filme de ficção científica de 2026. Consulte a apresentação, as informações de referência e a exibição no Brasil.',editorial_body='Project Hail Mary é uma produção cinematográfica de ficção científica associada a 2026. Para o espectador, a principal proposta é explorar uma narrativa do gênero, sem confundir a ficha da obra com um guia de disponibilidade comercial.

Os direitos de exibição mudam conforme o país e a janela de distribuição. Por isso, quando a plataforma brasileira não estiver confirmada, esta página indicará essa limitação com clareza. A fonte vinculada permite consultar informações adicionais sobre a produção, enquanto a disponibilidade local permanece sujeita a verificação.' where title='Project Hail Mary' and is_published=true;
update public.watch_titles set seo_title='The Devil Wears Prada 2: continuação e onde assistir',seo_description='Veja informações sobre a continuação de O Diabo Veste Prada e acompanhe a exibição de The Devil Wears Prada 2 no Brasil.',editorial_body='The Devil Wears Prada 2 é a continuação de O Diabo Veste Prada e faz parte da seleção de longas de 2026 do Guia de Hoje. A obra chama atenção de quem busca novos capítulos de histórias já conhecidas no cinema.

Não basta um título constar em catálogos internacionais para afirmar que ele esteja disponível no Brasil. Esta página separa os dados de referência sobre a produção das informações de lançamento e de streaming, que dependem de confirmação regional. A indicação de uma fonte externa ao final serve para consulta, e não substitui esta apresentação no portal.' where title='The Devil Wears Prada 2' and is_published=true;
update public.watch_titles set seo_title='The Mandalorian and Grogu: história e onde assistir',seo_description='Conheça The Mandalorian and Grogu, produção de Star Wars, e acompanhe informações confirmadas sobre exibição no Brasil.',editorial_body='The Mandalorian and Grogu faz parte do universo de Star Wars e acompanha personagens associados à série The Mandalorian. É uma produção de interesse para quem acompanha as histórias de Din Djarin e Grogu e procura uma nova aventura nesse universo.

O vínculo com uma franquia conhecida não permite concluir, por si só, em qual serviço brasileiro o filme será exibido. A janela de cinema, eventuais opções digitais e o catálogo por assinatura precisam de confirmação específica. A referência vinculada à ficha ajuda a acompanhar comunicados oficiais da produção.' where title='The Mandalorian and Grogu' and is_published=true;
update public.watch_titles set seo_title='Michael (2026): cinebiografia e onde assistir',seo_description='Conheça Michael, cinebiografia musical de 2026, com informações sobre a obra e orientações para conferir a disponibilidade no Brasil.',editorial_body='Michael é uma cinebiografia musical incluída na seleção de filmes de 2026. A proposta do gênero é apresentar uma trajetória artística para o público do cinema, aproximando música e narrativa biográfica em uma mesma produção.

Nesta ficha, o Guia de Hoje prioriza informações de identificação da obra e evita atribuir serviços de exibição sem confirmação brasileira. A presença de uma página de referência ou de um título na programação internacional não demonstra disponibilidade em assinatura, aluguel ou salas nacionais. Consulte as fontes vinculadas para verificar as atualizações da distribuição.' where title='Michael' and is_published=true;
update public.watch_titles set seo_title='The Odyssey (2026): filme, história e onde assistir',seo_description='Veja a ficha de The Odyssey, produção épica de 2026, com contexto sobre o filme e informações de exibição no Brasil.',editorial_body='The Odyssey é uma produção de 2026 associada ao gênero épico, categoria marcada por narrativas de grande escala e personagens inseridos em acontecimentos extraordinários. Para o público, a obra chama atenção pelo tema ligado à tradição das histórias de aventura.

Uma ficha internacional de cinema permite reconhecer a produção, mas não determina automaticamente a oferta no Brasil. O Guia de Hoje mantém separadas as informações sobre o título e as opções verificadas de exibição, para que o leitor não confunda estreia, aluguel digital e assinatura. A disponibilidade local será sinalizada quando houver fonte confiável.' where title='The Odyssey' and is_published=true;
update public.watch_titles set seo_title='Toy Story 5: sinopse, novidades e onde assistir no Brasil',seo_description='Conheça Toy Story 5, o novo capítulo da animação da Pixar. Saiba o que acompanhar sobre lançamento, história e plataformas de exibição no Brasil.',editorial_body='Toy Story 5 retoma o universo de brinquedos da Pixar em mais um capítulo da franquia de animação. É um título voltado especialmente a quem acompanhou os filmes anteriores e quer conhecer a continuação dessa história.

O principal ponto para o público brasileiro é distinguir anúncio ou lançamento da disponibilidade real para assistir. Uma estreia nos cinemas não significa entrada imediata em um catálogo de streaming: datas e serviços dependem da distribuição em cada mercado. Esta ficha será atualizada quando houver uma indicação verificável de exibição no Brasil.' where title='Toy Story 5' and is_published=true;
update public.watch_titles set seo_title='Stranger Things: história da série e onde assistir',seo_description='Relembre a proposta de Stranger Things, seus elementos de mistério e ficção científica, e consulte informações verificadas sobre disponibilidade no Brasil.',editorial_body='Stranger Things é uma série de mistério e ficção científica ambientada em torno de personagens e acontecimentos extraordinários. A produção combina referências da cultura popular com uma história seriada, sendo uma opção recorrente de interesse entre fãs do gênero.

A sinopse da obra e a referência de produção ajudam quem ainda não conhece a série a entender sua proposta. Para escolher onde assistir, considere que catálogos digitais mudam ao longo do tempo e podem variar por país e temporada. A plataforma brasileira só deve aparecer como confirmada aqui quando houver fonte específica.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/595/1489169.jpg' where title='Stranger Things' and is_published=true;
update public.watch_titles set seo_title='Fallout: série, sinopse e onde assistir no Brasil',seo_description='Veja a sinopse de Fallout, série inspirada na franquia de videogames, e acompanhe informações verificadas de programação e streaming brasileiro.',editorial_body='Fallout transporta para a televisão um universo associado à conhecida franquia de jogos eletrônicos. A proposta mistura elementos de ficção científica, ação e ambientes de um mundo pós-apocalíptico, o que ajuda a situar o tipo de narrativa apresentado pela série.

Esta ficha traz a sinopse de referência do TVmaze e uma indicação transparente sobre disponibilidade no Brasil. Mesmo quando uma série possui distribuição internacional conhecida, é necessário diferenciar o serviço em cada país e a presença de temporadas específicas no catálogo. A referência externa é oferecida para consulta dos dados de produção.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/599/1499142.jpg' where title='Fallout' and is_published=true;
update public.watch_titles set seo_title='Wednesday: série de mistério e onde assistir',seo_description='Conheça Wednesday, série de comédia e mistério, e acompanhe informações sobre temporadas e disponibilidade confirmada no Brasil.',editorial_body='Wednesday combina mistério e humor em uma série centrada na personagem conhecida no Brasil como Wandinha. A mistura de investigação, situações incomuns e referências ao universo da personagem caracteriza a proposta da produção.

Esta ficha funciona como ponto de partida para conhecer o título e consultar sua página de referência. Para quem procura onde assistir, o Guia de Hoje evita confundir informação de estreia internacional com acesso no Brasil. A disponibilidade de temporadas e episódios pode variar, e apenas fontes verificadas devem fundamentar a indicação de plataformas.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/586/1466410.jpg' where title='Wednesday' and is_published=true;
update public.watch_titles set seo_title='The Boys: história, personagens e onde assistir',seo_description='Conheça a proposta de The Boys, série de super-heróis com ação e sátira, e veja como consultar disponibilidade confirmada no Brasil.',editorial_body='The Boys explora uma abordagem satírica do universo de super-heróis, combinando ação, fantasia e conflitos de poder. A produção se distingue pela maneira como apresenta figuras superpoderosas e as consequências de suas decisões para a sociedade.

Esta página oferece uma visão inicial do gênero e da obra antes de encaminhar o visitante à fonte de referência. Para assistir legalmente no Brasil, é importante confirmar a plataforma e as temporadas disponíveis, pois catálogos e licenças mudam. Na ausência de comprovação regional, o Guia de Hoje mantém a informação como não confirmada.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/619/1547768.jpg' where title='The Boys' and is_published=true;
update public.watch_titles set seo_title='The Bear: sobre a série e onde assistir no Brasil',seo_description='Saiba mais sobre The Bear, série com drama e comédia no ambiente de cozinha, e acompanhe os dados de disponibilidade no streaming brasileiro.',editorial_body='The Bear acompanha personagens envolvidos na rotina de um negócio de alimentação, combinando drama, relações profissionais e momentos de humor. O ambiente de cozinha é parte central de sua identidade e ajuda a diferenciá-la de outras séries contemporâneas.

A ficha reúne a descrição de referência e informações de acompanhamento, sem tratar rumores de catálogo como confirmação. Quem procura uma temporada específica deve verificar se ela está incluída na oferta brasileira do serviço consultado. A existência de distribuição estrangeira não prova automaticamente que todas as temporadas estejam acessíveis no Brasil.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/629/1574642.jpg' where title='The Bear' and is_published=true;
update public.watch_titles set seo_title='The Last of Us: série, história e onde assistir',seo_description='Conheça The Last of Us, adaptação para televisão de uma história pós-apocalíptica, com sinopse e verificação de streaming no Brasil.',editorial_body='The Last of Us leva à televisão uma narrativa de sobrevivência em um cenário pós-apocalíptico. A história é conhecida pelo foco nos personagens e nos vínculos criados em meio a situações extremas, além da relação com o universo dos videogames.

O Guia de Hoje apresenta a obra para quem procura séries de drama e suspense, com indicação da fonte de referência. A possibilidade de assistir no Brasil exige comprovação para a plataforma e a temporada desejada: um catálogo estrangeiro ou uma página promocional não bastam para afirmar disponibilidade regional.',poster_url='https://static.tvmaze.com/uploads/images/medium_portrait/563/1409008.jpg' where title='The Last of Us' and is_published=true;
